
module.exports = function (RED) {
  function RabbitmqBroker(n) {
    RED.nodes.createNode(this, n)
    this.name = n.name
    this.host = n.host
    this.port = n.port
    this.tls = n.tls
    this.vhost = n.vhost
    this.credsFromSettings = n.credsFromSettings
  }
  RED.nodes.registerType('rabbitmq-broker', RabbitmqBroker, {
    credentials: {
      username: { type: 'text' },
      password: { type: 'password' },
    },
  })
}